import * as fs from 'fs';

interface Edge {
  from: string;
  to: string;
  weight: number;
}

interface GraphData {
  nodes: string[];
  edges: Edge[];
}

const filePath = '__FIXTURE_DIR__/graph.json';
const data: GraphData = JSON.parse(fs.readFileSync(filePath, 'utf-8'));

// Build adjacency list (undirected graph)
const adj: Map<string, { to: string; weight: number }[]> = new Map();
for (const node of data.nodes) {
  adj.set(node, []);
}
for (const edge of data.edges) {
  adj.get(edge.from)!.push({ to: edge.to, weight: edge.weight });
  adj.get(edge.to)!.push({ to: edge.from, weight: edge.weight });
}

// Dijkstra's algorithm from node "A"
const dist: Map<string, number> = new Map();
const visited: Set<string> = new Set();

for (const node of data.nodes) {
  dist.set(node, Infinity);
}
dist.set('A', 0);

while (true) {
  let minDist = Infinity;
  let minNode: string | null = null;
  for (const node of data.nodes) {
    if (!visited.has(node) && dist.get(node)! < minDist) {
      minDist = dist.get(node)!;
      minNode = node;
    }
  }
  if (minNode === null) break;
  visited.add(minNode);

  const neighbors = adj.get(minNode)!;
  for (const neighbor of neighbors) {
    const newDist = dist.get(minNode)! + neighbor.weight;
    if (newDist < dist.get(neighbor.to)!) {
      dist.set(neighbor.to, newDist);
    }
  }
}

// Output
console.log('=== Shortest Paths from A ===');
console.log('');
const sortedNodes = [...data.nodes].sort();
for (const node of sortedNodes) {
  console.log(`A -> ${node}: ${dist.get(node)}`);
}

