static void skip_ws(const char *s, int *pos, int len) {
    while (*pos < len && (s[*pos]==' '||s[*pos]=='\t'||s[*pos]=='\n'||s[*pos]=='\r'))
        (*pos)++;
}

static char *parse_string(const char *s, int *pos, int len) {
    if (*pos >= len || s[*pos] != '"') return NULL;
    (*pos)++;
    int start = *pos;
    int cap = 64;
    char *buf = malloc(cap);
    int blen = 0;
    while (*pos < len && s[*pos] != '"') {
        if (s[*pos] == '\\' && *pos + 1 < len) {
            (*pos)++;
            char c = s[*pos];
            char out = c;
            if (c == 'n') out = '\n';
            else if (c == 't') out = '\t';
            else if (c == 'r') out = '\r';
            else if (c == '\\') out = '\\';
            else if (c == '"') out = '"';
            else if (c == '/') out = '/';
            else if (c == 'b') out = '\b';
            else if (c == 'f') out = '\f';
            else if (c == 'u') {
                /* basic unicode: just skip 4 hex digits, output '?' */
                *pos += 4;
                out = '?';
            }
            if (blen + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); }
            buf[blen++] = out;
            (*pos)++;
        } else {
            if (blen + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); }
            buf[blen++] = s[*pos];
            (*pos)++;
        }
    }
    if (*pos < len && s[*pos] == '"') (*pos)++;
    buf[blen] = '\0';
    (void)start;
    return buf;
}

static double parse_number(const char *s, int *pos, int len) {
