static double dist[MAX_NODES];
static int visited[MAX_NODES];

int find_node(const char *name) {
    for (int i = 0; i < node_count; i++) {
        if (strcmp(nodes[i].name, name) == 0) return i;
    }
    return -1;
}

void add_node(const char *name) {
    if (find_node(name) == -1) {
        strncpy(nodes[node_count].name, name, 255);
        nodes[node_count].name[255] = '\0';
        head[node_count] = -1;
        node_count++;
    }
}

void add_edge(int u, int v, double w) {
    edges[edge_count].to = v;
    edges[edge_count].weight = w;
    edges[edge_count].next = head[u];
    head[u] = edge_count++;
}

void dijkstra(int src) {
    for (int i = 0; i < node_count; i++) {
        dist[i] = INF;
        visited[i] = 0;
    }
    dist[src] = 0.0;
    for (int iter = 0; iter < node_count; iter++) {
        int u = -1;
        double best = INF;
        for (int i = 0; i < node_count; i++) {
            if (!visited[i] && dist[i] < best) {
                best = dist[i];
                u = i;
            }
        }
        if (u == -1) break;
        visited[u] = 1;
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            double w = edges[e].weight;
            if (!visited[v] && dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
            }
        }
    }
}

