function countLines(buf: Buffer): number {
  if (buf.length === 0) return 0;
  let count = 0;
  for (let i = 0; i < buf.length; i++) {
    if (buf[i] === 10) count++;
  }
  if (buf[buf.length - 1] !== 10) count++;
  return count;
}

function walkDir(dir: string, base: string, files: FileInfo[]): void {
  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return;
  }
  for (const entry of entries) {
    if (entry.isSymbolicLink()) continue;
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      walkDir(fullPath, base, files);
    } else if (entry.isFile()) {
      const buf = fs.readFileSync(fullPath);
      const chars = buf.length;
      const lines = countLines(buf);
      const relPath = path.relative(base, fullPath).split(path.sep).join('/');
      files.push({ relPath, lines, chars });
    }
  }
}

