func pad(_ n: Int, width: Int) -> String {
    let s = String(n)
    if s.count >= width { return s }
    return String(repeating: " ", count: width - s.count) + s
}

func printMatrix(_ m: [[Int]]) {
    for row in m {
        let line = "  " + row.map { pad($0, width: 4) }.joined(separator: " ")
        print(line)
    }
}

