import Foundation

let rootPath = "__FIXTURE_DIR__/project_tree"
let rootURL = URL(fileURLWithPath: rootPath)

let fileManager = FileManager.default
var fileData: [(path: String, ext: String, lines: Int, chars: Int)] = []

let keys: [URLResourceKey] = [.isRegularFileKey, .isSymbolicLinkKey, .isDirectoryKey]

if let enumerator = fileManager.enumerator(at: rootURL, includingPropertiesForKeys: keys, options: [], errorHandler: { (_, _) -> Bool in
    return true
}) {
    for case let fileURL as URL in enumerator {
        let values = try? fileURL.resourceValues(forKeys: Set(keys))

        if values?.isSymbolicLink == true {
            continue
        }

        guard values?.isRegularFile == true else { continue }

        let relativePath = String(fileURL.path.dropFirst(rootPath.count + 1))
        let ext = fileURL.pathExtension
        let extDisplay = ext.isEmpty ? "" : ".\(ext)"

        if let data = try? Data(contentsOf: fileURL) {
            let charCount = data.count
            var lineCount = 0
            for byte in data {
                if byte == 0x0A {
                    lineCount += 1
                }
            }
            if !data.isEmpty && data.last != 0x0A {
                lineCount += 1
            }
            fileData.append((path: relativePath, ext: extDisplay, lines: lineCount, chars: charCount))
        }
    }
}

var groups: [String: [(path: String, lines: Int, chars: Int)]] = [:]
for f in fileData {
    groups[f.ext, default: []].append((path: f.path, lines: f.lines, chars: f.chars))
}

let sortedExts = groups.keys.sorted()

print("=== File Tree Analysis ===")
print("")

var totalFiles = 0
var totalLines = 0
var totalChars = 0

for ext in sortedExts {
    let files = groups[ext]!.sorted { $0.path < $1.path }
    let extFiles = files.count
    let extLines = files.reduce(0) { $0 + $1.lines }
    let extChars = files.reduce(0) { $0 + $1.chars }

    totalFiles += extFiles

